-- State transitions declared for Session (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.sessions_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'revoked'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: sessions.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS sessions_status_transition_check ON sapiens.sessions;
CREATE TRIGGER sessions_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.sessions
    FOR EACH ROW EXECUTE FUNCTION sapiens.sessions_status_transition_check();
